// FUNCTIONS //

/**
* Tests whether two values are approximately equal.
*
* @private
* @param {Object} t - test object
* @param {number} actual - actual value
* @param {number} expected - expected value
* @param {string} msg - message
*/
function isApprox( t, actual, expected, msg ) {
	var delta;
	var tol;

	if ( actual === expected ) {
		t.strictEqual( actual, expected, msg );
	} else {
		delta = abs( actual - expected );
		tol = 20.0 * EPS * abs( expected );
		t.ok( delta <= tol, msg + '. Expected: ' + expected + '. Actual: ' + actual + '. Delta: ' + delta + '. Tol: ' + tol + '.' );
	}
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlansy, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 7', function test( t ) {
	t.strictEqual( dlansy.length, 7, 'returns expected value' );
	t.end();
});

tape( 'the function returns 0 when N is 0', function test( t ) {
	var A = new Float64Array( [ 1.0 ] );
	var v;

	v = dlansy( 'M', 'upper', 0, A, 1, 1, 0 );
	t.strictEqual( v, 0.0, 'returns expected value' );

	t.end();
});

tape( 'the function computes the max norm (row-major, upper)', function test( t ) {
	var data = MAX_NORM_ROW_MAJOR_UPPER;
	var v = dlansy( data.norm, data.uplo, data.N, new Float64Array( data.A ), data.strideA1, data.strideA2, data.offsetA );
	t.strictEqual( v, data.expected, 'returns expected value' );
	t.end();
});

