tape( 'if provided an invalid norm type, the function returns 0.0', function test( t ) {
	var A;
	var v;

	A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );

	v = dlansy( 'Z', 'upper', 2, A, 2, 1, 0 );
	t.strictEqual( v, 0.0, 'returns expected value' );

	t.end();
});
